package com.bank.statement.service;

import com.bank.statement.model.TxnNode;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Merges K sorted transaction lists into one sorted list using a size-K min-heap.
public class StatementMergeService {
    private static final Logger log = Logger.getLogger(StatementMergeService.class.getName());

    public TxnNode mergeKLists(List<TxnNode> lists) {
        // Min-heap keyed by transaction amount; holds at most K candidate heads.
        PriorityQueue<TxnNode> pq = new PriorityQueue<>((a, b) -> Integer.compare(a.amount, b.amount));
        for (TxnNode head : lists) {
            if (head != null) pq.add(head);     // seed one head per non-empty list
        }
        TxnNode dummy = new TxnNode(0);          // dummy removes first-append special case
        TxnNode tail = dummy;
        while (!pq.isEmpty()) {
            TxnNode smallest = pq.poll();        // global minimum across all lists
            tail.next = smallest;
            tail = smallest;
            if (smallest.next != null) {
                pq.add(smallest.next);           // bring next candidate from same list
            }
        }
        log.info(() -> "Merged " + lists.size() + " sorted lists into one");
        return dummy.next;
    }
}
