package com.bank.statement;

import com.bank.statement.model.TxnNode;
import com.bank.statement.service.StatementMergeService;
import java.util.List;
import java.util.logging.Logger;

public class StatementMergeApplication {
    private static final Logger log = Logger.getLogger(StatementMergeApplication.class.getName());

    public static void main(String[] args) {
        StatementMergeService service = new StatementMergeService();
        TxnNode a = node(100, 400, 900);        // account 1 sorted amounts
        TxnNode b = node(250, 500, 700);        // account 2 sorted amounts
        TxnNode c = node(150, 600);             // account 3 sorted amounts
        TxnNode merged = service.mergeKLists(List.of(a, b, c));
        StringBuilder sb = new StringBuilder();
        for (TxnNode n = merged; n != null; n = n.next) sb.append(n.amount).append(' ');
        log.info("Merged order: " + sb.toString().trim());
    }

    private static TxnNode node(int... amounts) {
        TxnNode head = null, tail = null;
        for (int v : amounts) {
            TxnNode n = new TxnNode(v);
            if (head == null) { head = tail = n; } else { tail.next = n; tail = n; }
        }
        return head;
    }
}
